(function(){
'use strict';
const button=document.createElement('button');button.id='setwalkstart';button.textContent='Set start';button.title='Place walkthrough start: click, then drag to face a direction';button.setAttribute('aria-pressed','false');
let placing=false,gesture=null,validator=null,scope=null;
function pointAt(e){const p=$('plan').createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform($('plan').getScreenCTM().inverse());}
function finish(){placing=false;gesture=null;validator=null;button.setAttribute('aria-pressed','false');$('plan').style.cursor='';draw();}
function markup(){const p=gesture?.next||model.walkStart;if(!p||p.floor!==floorId)return '';const valid=!gesture||gesture.valid,color=valid?'#56bcda':'#df6868',size=Math.max(.65,worldPixels(17));return `<g data-walkstart="true" transform="translate(${p.x} ${p.y})" style="cursor:grab"><title>Walk start · drag the arrow to change facing</title><circle r="${size*.5}" fill="#162d39" stroke="${color}" stroke-width="${size*.1}"/><g transform="rotate(${-p.yaw*180/Math.PI})"><path d="M0 ${-size*.2} V${-size*1.65} M${-size*.35} ${-size*1.2} L0 ${-size*1.65} L${size*.35} ${-size*1.2}" fill="none" stroke="${color}" stroke-width="${size*.17}" stroke-linecap="round" stroke-linejoin="round"/></g><text y="${size*1.05}" text-anchor="middle" fill="${color}" style="font-size:${size*.5}px;font-family:Arial,sans-serif;paint-order:stroke;stroke:#162d39;stroke-width:${size*.07}px">START</text></g>`;}
async function activate(){if(placing){finish();return;}if(window.KERN_EXPLORER?.active)window.KERN_EXPLORER.stop();if(window.BuildingExports.isThreeMode())await window.BuildingExports.setWorkspaceMode('2d');resetTransient(true);validator=window.KERN_WALK.create(window.BuildingExports.currentGeometry());scope=currentBuilding().id;placing=true;button.setAttribute('aria-pressed','true');$('plan').style.cursor='crosshair';notify('Click to place start; drag toward the direction to face');}
function supportedStart(p){const r=floor().rooms.find(r=>!['void','solid'].includes(r.type)&&p.x>=r.x&&p.x<=r.x+r.w&&p.y>=r.y&&p.y<=r.y+r.h),z=r?.z??floor().z;const q=validator.findPlacement({x:snap(p.x),y:snap(p.y),z,floor:floorId})?.position;return q?.floor===floorId?q:null;}
$('plan').addEventListener('pointerdown',e=>{const marker=e.target.closest?.('[data-walkstart]');if((!placing&&!marker)||e.button!==0||window.KERN_EXPLORER?.active)return;e.preventDefault();e.stopImmediatePropagation();if(!validator){validator=window.KERN_WALK.create(window.BuildingExports.currentGeometry());scope=currentBuilding().id;}const p=pointAt(e),origin=marker&&!placing?window.BuildingExports.currentGeometry().walkStart:supportedStart(p);if(!origin){notify('Choose clear floor space for the character');return;}const anchor=floor().rooms.find(r=>!['void','solid'].includes(r.type)&&origin.x>=r.x&&origin.x<=r.x+r.w&&origin.y>=r.y&&origin.y<=r.y+r.h);gesture={pointerId:e.pointerId,next:{floor:floorId,x:origin.x,y:origin.y,z:origin.z,yaw:origin.yaw??model.walkStart?.yaw??0,floorZ:floor().z,anchorRoom:anchor?.id,baseZ:anchor?.z??floor().z},valid:true};$('plan').setPointerCapture?.(e.pointerId);draw();},true);
$('plan').addEventListener('pointermove',e=>{if(!gesture||gesture.pointerId!==e.pointerId)return;e.preventDefault();e.stopImmediatePropagation();const p=pointAt(e),dx=p.x-gesture.next.x,dy=p.y-gesture.next.y;if(Math.hypot(dx,dy)>.2)gesture.next.yaw=-Math.atan2(dx,-dy);draw();},true);
$('plan').addEventListener('pointerup',e=>{if(!gesture||gesture.pointerId!==e.pointerId)return;e.preventDefault();e.stopImmediatePropagation();const p={...gesture.next};gesture=null;if($('plan').hasPointerCapture?.(e.pointerId))$('plan').releasePointerCapture(e.pointerId);const valid=scope===currentBuilding().id&&p.floor===floorId;finish();if(valid){commit(()=>{model.walkStart=p;});notify('Walk start saved');}},true);
for(const name of ['pointercancel','lostpointercapture'])$('plan').addEventListener(name,()=>{if(gesture)finish();},true);document.addEventListener('pointerdown',e=>{if((placing||gesture)&&!$('plan').contains(e.target)&&e.target!==button)finish();},true);
window.addEventListener('keydown',e=>{if(placing&&!isTypingTarget(e.target)&&['r','c','x','d','b','v','w','s'].includes(e.key.toLowerCase()))finish();if(e.key==='Escape'&&(placing||gesture)){e.preventDefault();e.stopImmediatePropagation();finish();}},true);
window.addEventListener('blur',()=>{if(placing||gesture)finish();});button.onclick=activate;
window.KERN_START={markup,activate,place(p){validator=window.KERN_WALK.create(window.BuildingExports.currentGeometry());const q=supportedStart(p);if(!q){validator=null;notify('Choose clear floor space for the character');return false;}const anchor=floor().rooms.find(r=>!['void','solid'].includes(r.type)&&q.x>=r.x&&q.x<=r.x+r.w&&q.y>=r.y&&q.y<=r.y+r.h);const next={floor:floorId,x:q.x,y:q.y,z:q.z,yaw:model.walkStart?.yaw??0,floorZ:floor().z,anchorRoom:anchor?.id,baseZ:anchor?.z??floor().z};finish();resetTransient(true);commit(()=>{model.walkStart=next;});notify('Walk start placed · drag its arrow to change facing');return true;},clear(){finish();if(model.walkStart)commit(()=>delete model.walkStart);}};
draw();
})();
